create or replace function public.get_nearby_profiles(p_max_distance_km integer default 10) returns table(id uuid,display_name text,age integer,city text,bio text,photo_url text,interests text[],looking_for text,distance_band text) language plpgsql stable security definer set search_path=public as $$ declare v_user uuid:=auth.uid(); v_lat double precision; v_lon double precision; v_radius integer; begin if v_user is null then raise exception 'Sign in required'; end if; v_radius:=case when p_max_distance_km in (5,10,50) then p_max_distance_km else 10 end; select latitude,longitude into v_lat,v_lon from public.member_location_preferences where user_id=v_user; if v_lat is null or v_lon is null then return; end if; return query select p.id,p.display_name,p.age,p.city,p.bio,p.photo_url,p.interests,p.looking_for,case when dist.km<=5 then 'Within 5 km' when dist.km<=10 then 'Within 10 km' else 'Within 50 km' end from public.profiles p join public.member_location_preferences loc on loc.user_id=p.id and loc.share_nearby=true and loc.latitude is not null and loc.longitude is not null cross join lateral (select 6371*acos(least(1,greatest(-1,sin(radians(v_lat))*sin(radians(loc.latitude))+cos(radians(v_lat))*cos(radians(loc.latitude))*cos(radians(loc.longitude-v_lon))))) as km) dist where p.id<>v_user and dist.km<=v_radius and not exists(select 1 from public.member_blocks b where (b.blocker_id=v_user and b.blocked_user_id=p.id) or (b.blocker_id=p.id and b.blocked_user_id=v_user)) and not exists(select 1 from public.member_safety_status s where s.user_id=p.id and s.suspended_until>now()) order by dist.km asc limit 200; end $$; revoke execute on function public.get_nearby_profiles(integer) from anon,public; grant execute on function public.get_nearby_profiles(integer) to authenticated;